-- ============================================================
-- Mapare descrieri RO (coloana V8) -> products.short_description
-- Potrivire dupa SKU (products.sku = PDT_SUP_REF din pricelist)
-- 16163 descrieri; ruleaza integral in Supabase SQL Editor
-- ============================================================
BEGIN;

CREATE TEMP TABLE _pferd_desc (sku text PRIMARY KEY, short_description text) ON COMMIT DROP;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

