ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

ON CONFLICT (sku) DO UPDATE SET short_description = EXCLUDED.short_description;

-- Aplica descrierile pe produsele existente (doar unde SKU-ul se potriveste)
UPDATE products p
SET short_description = d.short_description
FROM _pferd_desc d
WHERE p.sku = d.sku;

-- Raport: cate produse au fost potrivite/actualizate
SELECT count(*) AS produse_actualizate
FROM products p JOIN _pferd_desc d ON p.sku = d.sku;

COMMIT;